<?php require_once __DIR__.'/chart_local.php'; function gridplot(){$q="SELECT COUNT(*),grid.name FROM site,grid WHERE last_activity>=DATE_SUB(NOW(),INTERVAL 2 MONTH) AND fstype NOT IN ('','-') AND site.gridfk=grid.ref AND status=1 AND cs<>cename AND cs<>'unassigned' AND cs NOT LIKE '%_Install' GROUP BY grid.name ORDER BY COUNT(*) DESC";$r=db_query($q,'ro');$d=[];while($x=mysqli_fetch_row($r))$d[]=[$x[1],(float)$x[0]];echo '<div id="gridchart_div">'.atlas_chart_pie($d,'Grid Resources (active sites)').'</div>';}
